// Generates `src/engine/tables.ts` from the packed plan tables of the contracts,
// `contracts/src/structure/tables.cairo` (the rows of `plan_row` and `area_row_<plan>`), decoded
// field by field as that file's header documents them. The tables are never copied by hand: run
// `bun run generate:tables` in `packages/game-core` after the Cairo tables change, and
// `__tests__/engine-tables.test.ts` fails while the generated file is out of date.

import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
export const TABLES_SOURCE = resolve(HERE, "../../../contracts/src/structure/tables.cairo");
export const TABLES_TARGET = resolve(HERE, "../src/engine/tables.ts");

/** The row of an area that a plan does not have (`ABSENT` in the Cairo tables). */
const ABSENT = 0x78n;

function field(row: bigint, shift: number, bits: number): number {
  return Number((row >> BigInt(shift)) & ((1n << BigInt(bits)) - 1n));
}

interface AreaRow {
  category: number;
  recordIndex: number;
  moves: [number, number][];
  halfEdges: number[];
  adjacentRoads: number;
  adjacentCities: number;
}

interface PlanRow {
  name: string;
  spots: number[];
  starts: number[];
  wonder: number;
  areas: (AreaRow | null)[];
}

function decodePlan(name: string, row: bigint): Omit<PlanRow, "areas"> {
  const spots: number[] = [];
  for (let spot = 1; spot <= 9; spot++) spots.push(field(row, 4 * (spot - 1), 4));
  const count = field(row, 36, 4);
  const starts: number[] = [];
  for (let index = 0; index < count; index++) starts.push(field(row, 40 + 4 * index, 4));
  return { name, spots, starts, wonder: field(row, 72, 4) };
}

function decodeArea(row: bigint): AreaRow | null {
  if (row === ABSENT) return null;
  const count = field(row, 7, 4);
  const moves: [number, number][] = [];
  for (let index = 0; index < count; index++) {
    const byte = field(row, 11 + 8 * index, 8);
    moves.push([byte % 16, Math.floor(byte / 16)]);
  }
  const halfEdges: number[] = [];
  for (let direction = 1; direction <= 8; direction++) {
    halfEdges.push(field(row, 75 + 4 * (direction - 1), 4));
  }
  return {
    category: field(row, 0, 3),
    recordIndex: field(row, 3, 4),
    moves,
    halfEdges,
    adjacentRoads: field(row, 107, 9),
    adjacentCities: field(row, 116, 9),
  };
}

/** Parses the Cairo tables and returns the decoded plans, indexed by plan code (0 is none). */
export function parseTables(source: string): (PlanRow | null)[] {
  const planBody = source.match(/pub fn plan_row\(plan: u8\) -> u128 \{([\s\S]*?)\n\}/);
  if (!planBody) throw new Error("tables.cairo: plan_row not found");
  const plans: (PlanRow | null)[] = [null];
  for (const match of planBody[1].matchAll(/(\d+) => 0x([0-9a-f]+), \/\/ ([A-Z]+)/g)) {
    const code = Number(match[1]);
    if (code !== plans.length) throw new Error(`tables.cairo: plan ${code} out of order`);
    const areaBody = source.match(
      new RegExp(`fn area_row_${code}\\(area: u8\\) -> u128 \\{([\\s\\S]*?)\\n\\}`),
    );
    if (!areaBody) throw new Error(`tables.cairo: area_row_${code} not found`);
    const areas: (AreaRow | null)[] = [];
    for (let area = 1; area <= 9; area++) areas.push(null);
    for (const row of areaBody[1].matchAll(/(\d) => 0x([0-9a-f]+),/g)) {
      areas[Number(row[1]) - 1] = decodeArea(BigInt(`0x${row[2]}`));
    }
    plans.push({ ...decodePlan(match[3], BigInt(`0x${match[2]}`)), areas });
  }
  if (plans.length !== 20) throw new Error(`tables.cairo: ${plans.length - 1} plans, expected 19`);
  return plans;
}

/** Returns the content of `src/engine/tables.ts` for the Cairo tables `source`. */
export function generateTables(source: string): string {
  const plans = parseTables(source);
  const lines = [
    "// Generated by `scripts/generate-tables.ts` from `contracts/src/structure/tables.cairo`: do not",
    "// edit. Run `bun run generate:tables` in `packages/game-core` to regenerate it.",
    "//",
    "// One row per plan code (0 is none), in the north-oriented frame of the plan. Codes are those of",
    "// the contracts: spots 1 (center), 2..=9 (north-west, north, ..., west); directions 1..=8",
    "// (north-west, north, ..., west); areas 1..=9; categories 0 none, 1 forest, 2 road, 3 city,",
    "// 4 stop, 5 wonder.",
    "// - `spots[spot - 1]`: the area of each spot;",
    "// - `starts`: the start spots in `starts()` order; `wonder`: the wonder spot (1, or 0 for none);",
    "// - `areas[area - 1]`: `null` when the plan has no such area, else its category, its record",
    "//   index (15 when the area has no move), its moves `[direction, spot]` (spot 0: a wonder's",
    "//   half-edge, which only asks for the tile), its half-edges per direction 1..=8, and the road",
    "//   and city areas adjacent to it (bit `area - 1`).",
    "",
    "export interface AreaRow {",
    "  readonly category: number;",
    "  readonly recordIndex: number;",
    "  readonly moves: readonly (readonly [number, number])[];",
    "  readonly halfEdges: readonly number[];",
    "  readonly adjacentRoads: number;",
    "  readonly adjacentCities: number;",
    "}",
    "",
    "export interface PlanRow {",
    "  readonly name: string;",
    "  readonly spots: readonly number[];",
    "  readonly starts: readonly number[];",
    "  readonly wonder: number;",
    "  readonly areas: readonly (AreaRow | null)[];",
    "}",
    "",
    "export const PLAN_ROWS: readonly (PlanRow | null)[] = [",
    "  null,",
  ];
  for (const plan of plans.slice(1)) {
    const row = plan as PlanRow;
    lines.push("  {");
    lines.push(`    name: "${row.name}",`);
    lines.push(`    spots: ${JSON.stringify(row.spots)},`);
    lines.push(`    starts: ${JSON.stringify(row.starts)},`);
    lines.push(`    wonder: ${row.wonder},`);
    lines.push("    areas: [");
    for (const area of row.areas) {
      if (area === null) {
        lines.push("      null,");
        continue;
      }
      lines.push(
        `      { category: ${area.category}, recordIndex: ${area.recordIndex}, ` +
          `moves: ${JSON.stringify(area.moves)}, halfEdges: ${JSON.stringify(area.halfEdges)}, ` +
          `adjacentRoads: ${area.adjacentRoads}, adjacentCities: ${area.adjacentCities} },`,
      );
    }
    lines.push("    ],");
    lines.push("  },");
  }
  lines.push("];", "");
  return lines.join("\n");
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  writeFileSync(TABLES_TARGET, generateTables(readFileSync(TABLES_SOURCE, "utf8")));
  console.log(`Wrote ${TABLES_TARGET}`);
}
